import{c as a,Q as o,j as e,m as l}from"./chunks/framework.CHJbb1iY.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{"outline":[2,3],"sidebar":"tue","aside":"right"},"headers":[],"relativePath":"docs/Java/第一阶段/基本语法/9.编码.md","filePath":"docs/Java/第一阶段/基本语法/9.编码.md"}'),s={name:"docs/Java/第一阶段/基本语法/9.编码.md"};function r(n,t,c,d,i,p){return o(),e("div",null,[...t[0]||(t[0]=[l('<h1 style="text-align:center;font-weight:bold;">编码</h1><hr><h2 id="一、类型介绍" tabindex="-1">一、类型介绍 <a class="header-anchor" href="#一、类型介绍" aria-label="Permalink to &quot;一、类型介绍&quot;">​</a></h2><h4 id="_1-ascii-ascii-编码表-一个字符表示一个字节-每个字符用一个字节表示-实际上一个字节可以表示-256-个字符-在-ascll-码表中只用-128-个" tabindex="-1">（1）<span style="color:red;">ASCII</span> (ASCII 编码表 <span style="color:red;">一个字符表示一个字节</span>（每个字符用一个字节表示）；实际上一个字节可以表示 <span style="color:red;">256</span> 个字符，在 ASCll 码表中只用 <span style="color:red;">128</span> 个) <a class="header-anchor" href="#_1-ascii-ascii-编码表-一个字符表示一个字节-每个字符用一个字节表示-实际上一个字节可以表示-256-个字符-在-ascll-码表中只用-128-个" aria-label="Permalink to &quot;（1）&lt;span style=&quot;color:red&quot;&gt;ASCII&lt;/span&gt; (ASCII 编码表 &lt;span style=&quot;color:red&quot;&gt;一个字符表示一个字节&lt;/span&gt;（每个字符用一个字节表示）；实际上一个字节可以表示 &lt;span style=&quot;color:red&quot;&gt;256&lt;/span&gt; 个字符，在 ASCll 码表中只用 &lt;span style=&quot;color:red&quot;&gt;128&lt;/span&gt; 个)&quot;">​</a></h4><h4 id="_2-unicode-unicode-编码表-固定大小的编码-使用两个字节来表示字符-字母和汉字统一都是用两个字节-这样浪费空间" tabindex="-1">（2） <span style="color:red;">Unicode</span> (Unicode 编码表 固定大小的编码 使用两个字节来表示字符，<span style="color:red;">字母和汉字统一</span>都是用<span style="color:red;">两个</span>字节，这样浪费空间) <a class="header-anchor" href="#_2-unicode-unicode-编码表-固定大小的编码-使用两个字节来表示字符-字母和汉字统一都是用两个字节-这样浪费空间" aria-label="Permalink to &quot;（2） &lt;span style=&quot;color:red&quot;&gt;Unicode&lt;/span&gt; (Unicode 编码表 固定大小的编码 使用两个字节来表示字符，&lt;span style=&quot;color:red&quot;&gt;字母和汉字统一&lt;/span&gt;都是用&lt;span style=&quot;color:red&quot;&gt;两个&lt;/span&gt;字节，这样浪费空间)&quot;">​</a></h4><h4 id="_3-utf-8-编码表-大小可变的编码-字母使用1-个字节-汉字使用3-个字节" tabindex="-1">（3）<span style="color:red;">UTF-8</span> (编码表，大小可变的编码 <span style="color:red;">字母</span>使用<span style="color:red;">1 个</span>字节，<span style="color:red;">汉字</span>使用<span style="color:red;">3 个</span>字节) <a class="header-anchor" href="#_3-utf-8-编码表-大小可变的编码-字母使用1-个字节-汉字使用3-个字节" aria-label="Permalink to &quot;（3）&lt;span style=&quot;color:red&quot;&gt;UTF-8&lt;/span&gt; (编码表，大小可变的编码 &lt;span style=&quot;color:red&quot;&gt;字母&lt;/span&gt;使用&lt;span style=&quot;color:red&quot;&gt;1 个&lt;/span&gt;字节，&lt;span style=&quot;color:red&quot;&gt;汉字&lt;/span&gt;使用&lt;span style=&quot;color:red&quot;&gt;3 个&lt;/span&gt;字节)&quot;">​</a></h4><h4 id="_4-gbk-可以表示汉字-而且范围广-字母使用1-个字节-汉字使用2-个字节" tabindex="-1">（4） <span style="color:red;">GBK</span> (可以表示汉字，而且范围广，<span style="color:red;">字母</span>使用<span style="color:red;">1 个</span>字节，<span style="color:red;">汉字</span>使用<span style="color:red;">2 个</span>字节)) <a class="header-anchor" href="#_4-gbk-可以表示汉字-而且范围广-字母使用1-个字节-汉字使用2-个字节" aria-label="Permalink to &quot;（4） &lt;span style=&quot;color:red&quot;&gt;GBK&lt;/span&gt; (可以表示汉字，而且范围广，&lt;span style=&quot;color:red&quot;&gt;字母&lt;/span&gt;使用&lt;span style=&quot;color:red&quot;&gt;1 个&lt;/span&gt;字节，&lt;span style=&quot;color:red&quot;&gt;汉字&lt;/span&gt;使用&lt;span style=&quot;color:red&quot;&gt;2 个&lt;/span&gt;字节))&quot;">​</a></h4><h4 id="_5-gb2312-可以表示汉字-gb2312-gbk" tabindex="-1">（5） <span style="color:red;">gb2312</span> (可以表示汉字，gb2312 &lt; gbk) <a class="header-anchor" href="#_5-gb2312-可以表示汉字-gb2312-gbk" aria-label="Permalink to &quot;（5） &lt;span style=&quot;color:red&quot;&gt;gb2312&lt;/span&gt; (可以表示汉字，gb2312 &lt; gbk)&quot;">​</a></h4><h4 id="_6-big5-码-繁体中文-台湾-香港" tabindex="-1">（6） <span style="color:red;">big5</span> 码 (<span style="color:red;">繁体中文</span>，台湾，香港) <a class="header-anchor" href="#_6-big5-码-繁体中文-台湾-香港" aria-label="Permalink to &quot;（6） &lt;span style=&quot;color:red&quot;&gt;big5&lt;/span&gt; 码 (&lt;span style=&quot;color:red&quot;&gt;繁体中文&lt;/span&gt;，台湾，香港)&quot;">​</a></h4><hr><h2 id="二、常用类型" tabindex="-1">二、常用类型 <a class="header-anchor" href="#二、常用类型" aria-label="Permalink to &quot;二、常用类型&quot;">​</a></h2><h3 id="utf-8" tabindex="-1">UTF-8 <a class="header-anchor" href="#utf-8" aria-label="Permalink to &quot;UTF-8&quot;">​</a></h3><blockquote><h4 id="_1-是在互联网使用最广的-unicode-的实现方式-改进" tabindex="-1">（1）是在互联网<span style="color:red;">使用最广</span>的 Unicode 的实现方式（改进） <a class="header-anchor" href="#_1-是在互联网使用最广的-unicode-的实现方式-改进" aria-label="Permalink to &quot;（1）是在互联网&lt;span style=&quot;color:red&quot;&gt;使用最广&lt;/span&gt;的 Unicode 的实现方式（改进）&quot;">​</a></h4><h4 id="_2-utf-8-是一种变长的编码方式。它可以使用-1-6-个字节表示一个字符-根据不同的字符而变化字节长度" tabindex="-1">（2）UTF-8 是一种<span style="color:red;">变长的编码</span>方式。它可以使用 <span style="color:red;">1-6 个字节表示一个字符</span>，根据不同的字符而变化字节长度 <a class="header-anchor" href="#_2-utf-8-是一种变长的编码方式。它可以使用-1-6-个字节表示一个字符-根据不同的字符而变化字节长度" aria-label="Permalink to &quot;（2）UTF-8 是一种&lt;span style=&quot;color:red&quot;&gt;变长的编码&lt;/span&gt;方式。它可以使用 &lt;span style=&quot;color:red&quot;&gt;1-6 个字节表示一个字符&lt;/span&gt;，根据不同的字符而变化字节长度&quot;">​</a></h4><h4 id="_3-使用大小可变的编码-字母使用1-个字节-汉字使用3-个字节" tabindex="-1">（3）使用大小可变的编码，<span style="color:red;">字母</span>使用<span style="color:red;">1 个</span>字节，<span style="color:red;">汉字</span>使用<span style="color:red;">3 个</span>字节 <a class="header-anchor" href="#_3-使用大小可变的编码-字母使用1-个字节-汉字使用3-个字节" aria-label="Permalink to &quot;（3）使用大小可变的编码，&lt;span style=&quot;color:red&quot;&gt;字母&lt;/span&gt;使用&lt;span style=&quot;color:red&quot;&gt;1 个&lt;/span&gt;字节，&lt;span style=&quot;color:red&quot;&gt;汉字&lt;/span&gt;使用&lt;span style=&quot;color:red&quot;&gt;3 个&lt;/span&gt;字节&quot;">​</a></h4></blockquote><h3 id="unicode" tabindex="-1">Unicode <a class="header-anchor" href="#unicode" aria-label="Permalink to &quot;Unicode&quot;">​</a></h3><blockquote><h4 id="_1-优点-使用一种编码-将世界上所有的符号都纳入其中。每一个字符都给了一个独一无二的编码-使用-unicode-没有乱码的问题" tabindex="-1">（1）优点：使用一种编码，将世界上所有的符号都纳入其中。每一个字符都给了一个独一无二的编码，使用 Unicode 没有乱码的问题 <a class="header-anchor" href="#_1-优点-使用一种编码-将世界上所有的符号都纳入其中。每一个字符都给了一个独一无二的编码-使用-unicode-没有乱码的问题" aria-label="Permalink to &quot;（1）优点：使用一种编码，将世界上所有的符号都纳入其中。每一个字符都给了一个独一无二的编码，使用 Unicode 没有乱码的问题&quot;">​</a></h4><h4 id="_2-缺点-一个英文字母和一个汉字都占用2-个字节-这对于存储空间来说是浪费" tabindex="-1">（2）缺点：一个英文<span style="color:red;">字母</span>和一个<span style="color:red;">汉字</span>都占用<span style="color:red;">2 个字节</span>，这对于存储空间来说是浪费 <a class="header-anchor" href="#_2-缺点-一个英文字母和一个汉字都占用2-个字节-这对于存储空间来说是浪费" aria-label="Permalink to &quot;（2）缺点：一个英文&lt;span style=&quot;color:red&quot;&gt;字母&lt;/span&gt;和一个&lt;span style=&quot;color:red&quot;&gt;汉字&lt;/span&gt;都占用&lt;span style=&quot;color:red&quot;&gt;2 个字节&lt;/span&gt;，这对于存储空间来说是浪费&quot;">​</a></h4><h4 id="_3-2-的-16-次方是-65536-所以最多编码是65536-个字符。" tabindex="-1">（3）2 的 16 次方是 65536，所以<span style="color:red;">最多编码</span>是<span style="color:red;">65536 个</span>字符。 <a class="header-anchor" href="#_3-2-的-16-次方是-65536-所以最多编码是65536-个字符。" aria-label="Permalink to &quot;（3）2 的 16 次方是 65536，所以&lt;span style=&quot;color:red&quot;&gt;最多编码&lt;/span&gt;是&lt;span style=&quot;color:red&quot;&gt;65536 个&lt;/span&gt;字符。&quot;">​</a></h4><h4 id="_4-编码-0-127-的字符是与-ascii-的编码一样。比如-a-在-ascii-码是-0x61-在-unicode-码是-0x0061-都对应-97。因为unicode-码兼容-ascii-码" tabindex="-1">（4）编码 0-127 的字符是与 ASCII 的编码一样。比如&#39;a&#39;在 ASCII 码是 0x61，在 unicode 码是 0x0061，都对应 97。因为<span style="color:red;">Unicode 码兼容 ASCII 码</span> <a class="header-anchor" href="#_4-编码-0-127-的字符是与-ascii-的编码一样。比如-a-在-ascii-码是-0x61-在-unicode-码是-0x0061-都对应-97。因为unicode-码兼容-ascii-码" aria-label="Permalink to &quot;（4）编码 0-127 的字符是与 ASCII 的编码一样。比如&#39;a&#39;在 ASCII 码是 0x61，在 unicode 码是 0x0061，都对应 97。因为&lt;span style=&quot;color:red&quot;&gt;Unicode 码兼容 ASCII 码&lt;/span&gt;&quot;">​</a></h4></blockquote><h3 id="ascii-码" tabindex="-1">ASCII 码 <a class="header-anchor" href="#ascii-码" aria-label="Permalink to &quot;ASCII 码&quot;">​</a></h3><blockquote><h4 id="_1-上个世纪-60-年代-美国制定了一套字符编码-使用一个字节-对英语字符与计算机之间的关系-做了统一规定。这被称为-ascii-码。ascii-码一共规定了-128-个字符的编码-只占用一个字节的后面-7-位-最前面的-1-位统一规定为-0" tabindex="-1">（1）上个世纪 60 年代，美国制定了一套字符编码（使用一个字节），对英语字符与计算机之间的关系，做了统一规定。这被称为 ASCII 码。<span style="color:red;">ASCII 码一共规定了 128 个字符的编码，只占用一个字节的后面 7 位，最前面的 1 位统一规定为 0</span> <a class="header-anchor" href="#_1-上个世纪-60-年代-美国制定了一套字符编码-使用一个字节-对英语字符与计算机之间的关系-做了统一规定。这被称为-ascii-码。ascii-码一共规定了-128-个字符的编码-只占用一个字节的后面-7-位-最前面的-1-位统一规定为-0" aria-label="Permalink to &quot;（1）上个世纪 60 年代，美国制定了一套字符编码（使用一个字节），对英语字符与计算机之间的关系，做了统一规定。这被称为 ASCII 码。&lt;span style=&quot;color:red&quot;&gt;ASCII 码一共规定了 128 个字符的编码，只占用一个字节的后面 7 位，最前面的 1 位统一规定为 0&lt;/span&gt;&quot;">​</a></h4><h4 id="_2-特别提示-一个字节可以表示-256-个字符-ascii-码只用了-128-个字符-规则-用一个字节表示一个字符" tabindex="-1">（2）特别提示：一个字节可以表示 256 个字符，ASCII 码<span style="color:red;">只用了 128 个字符</span>（规则：用一个字节表示一个字符） <a class="header-anchor" href="#_2-特别提示-一个字节可以表示-256-个字符-ascii-码只用了-128-个字符-规则-用一个字节表示一个字符" aria-label="Permalink to &quot;（2）特别提示：一个字节可以表示 256 个字符，ASCII 码&lt;span style=&quot;color:red&quot;&gt;只用了 128 个字符&lt;/span&gt;（规则：用一个字节表示一个字符）&quot;">​</a></h4><h4 id="_3-缺点-不能表示所有字符" tabindex="-1">（3）<span style="color:red;">缺点：不能表示所有字符</span> <a class="header-anchor" href="#_3-缺点-不能表示所有字符" aria-label="Permalink to &quot;（3）&lt;span style=&quot;color:red&quot;&gt;缺点：不能表示所有字符&lt;/span&gt;&quot;">​</a></h4></blockquote>',17)])])}const h=a(s,[["render",r]]);export{q as __pageData,h as default};
